import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <limits>
#include <algorithm>

// Generic kernel: reduce over middle dimension of a 3D tensor
// input shape: (outer, reduce, inner)
// output shape: (outer, inner)
// Uses a 2D launch configuration (grid.y over the small 'outer' dimension,
// grid.x/block.x over the 'inner' dimension) so that the outer/inner
// indices can be derived directly from block/thread indices instead of
// requiring an expensive per-thread integer division/modulo of a
// flattened index.
template <typename scalar_t>
__global__ void min_reduce_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int64_t outer,
    const int64_t reduce,
    const int64_t inner) {
    const int64_t inner_stride = (int64_t)blockDim.x * gridDim.x;
    for (int64_t outer_idx = blockIdx.y; outer_idx < outer; outer_idx += gridDim.y) {
        const int64_t outer_base = outer_idx * reduce * inner;
        for (int64_t inner_idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
             inner_idx < inner;
             inner_idx += inner_stride) {
            int64_t base = outer_base + inner_idx;
            scalar_t min_val0 = __ldg(&input[base]);
            scalar_t min_val1 = min_val0;
            scalar_t min_val2 = min_val0;
            scalar_t min_val3 = min_val0;
            int64_t r = 0;
            #pragma unroll 4
            for (; r + 3 < reduce; r += 4) {
                scalar_t v0 = __ldg(&input[base + r * inner]);
                scalar_t v1 = __ldg(&input[base + (r + 1) * inner]);
                scalar_t v2 = __ldg(&input[base + (r + 2) * inner]);
                scalar_t v3 = __ldg(&input[base + (r + 3) * inner]);
                if (v0 < min_val0) min_val0 = v0;
                if (v1 < min_val1) min_val1 = v1;
                if (v2 < min_val2) min_val2 = v2;
                if (v3 < min_val3) min_val3 = v3;
            }
            for (; r < reduce; ++r) {
                scalar_t v = __ldg(&input[base + r * inner]);
                if (v < min_val0) min_val0 = v;
            }
            scalar_t min_val = min_val0;
            if (min_val1 < min_val) min_val = min_val1;
            if (min_val2 < min_val) min_val = min_val2;
            if (min_val3 < min_val) min_val = min_val3;
            output[outer_idx * inner + inner_idx] = min_val;
        }
    }
}

torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim) {
    input = input.contiguous();

    auto sizes = input.sizes();
    int64_t ndim = sizes.size();

    if (dim < 0) {
        dim += ndim;
    }

    int64_t outer = 1;
    for (int64_t i = 0; i < dim; ++i) {
        outer *= sizes[i];
    }
    int64_t reduce = sizes[dim];
    int64_t inner = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) {
        inner *= sizes[i];
    }

    std::vector<int64_t> out_sizes;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) {
            out_sizes.push_back(sizes[i]);
        }
    }

    auto output = torch::empty(out_sizes, input.options());

    const int threads = 256;
    const int64_t blocks_x = (inner + threads - 1) / threads;
    const int64_t blocks_y = outer;
    dim3 grid((unsigned int)std::min<int64_t>(blocks_x, (int64_t)65535),
              (unsigned int)std::min<int64_t>(blocks_y, (int64_t)65535));
    dim3 block(threads);
    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "min_reduce_cuda", ([&] {
        min_reduce_kernel<scalar_t><<<grid, block>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            outer,
            reduce,
            inner
        );
    }));

    return output;
}
"""

min_reduce_cpp_source = r"""
torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim);
"""

min_reduce_module = load_inline(
    name="min_reduce_module",
    cpp_sources=min_reduce_cpp_source,
    cuda_sources=min_reduce_source,
    functions=["min_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs min reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.min_reduce = min_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.min_reduce.min_reduce_cuda(x, self.dim)

